fn solve(a: i8, b: i8, s: Vec<char>) -> Vec<char> {
    // We have the input conditions:
    // 1 <= a,b <= 5
    // s.len() == a + b + 1
    // chars are digits or '-'

    // We want to check:
    // - Exactly one hyphen, at index a
    // - All other positions digits
    // Then return ['Y', 'e', 's'], else ['N', 'o']

    // First, count hyphens and check correctness in one pass.

    let mut hyphen_count = 0;
    for (i, &ch) in s.iter().enumerate() {
        if ch == '-' {
            hyphen_count += 1;
            if i != a as usize {
                // Hyphen in wrong place => No
                return vec!['N', 'o'];
            }
        } else {
            // Must be digit:
            if ch < '0' || ch > '9' {
                return vec!['N', 'o'];
            }
        }
    }

    if hyphen_count == 1 {
        vec!['Y','e','s']
    } else {
        vec!['N','o']
    }
}